def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: int, the timestamp in nanoseconds
    :param tz: timezone, the timezone to use for the conversion, if None, UTC is used
    :return: datetime, the corresponding datetime object
    """
    if tz is None:
        tz = timezone.utc

    try:
        seconds = nanoseconds // 1_000_000_000
        microseconds = (nanoseconds % 1_000_000_000) // 1_000
        dt = datetime.utcfromtimestamp(seconds) + timedelta(microseconds=microseconds)
        return dt.replace(tzinfo=tz)
    except TypeError as e:
        raise TypeError("Invalid input: nanoseconds must be an integer and tz must be a timezone object") from e
    except OverflowError as e:
        raise OverflowError("Invalid input: nanoseconds value is out of the valid range for a timestamp") from e
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}") from e

