def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Apply metadata if provided
            if metadata is not None:
                for tx in args:
                    tx.metadata = metadata
            # Apply timeout if provided
            if timeout is not None:
                for tx in args:
                    tx.timeout = timeout
            return func(*args, **kwargs)
        return wrapper
    return decorator

def unit_of_work(func=None, metadata=None, timeout=None):
    if func is None:
        return lambda f: unit_of_work(f, metadata, timeout)

    def wrapper(tx):
        if metadata is not None:
            try:
                tx.run("CALL dbms.setTXMetaData($metadata)", metadata=metadata)
            except Exception as e:
                raise Exception("Failed to set transaction metadata") from e

        if timeout is not None:
            try:
                tx.run("CALL dbms.setTXTimeout($timeout)", timeout=timeout)
            except Exception as e:
                raise Exception("Failed to set transaction timeout") from e

        try:
            return func(tx)
        except Exception as e:
            raise Exception("Transaction failed") from e

    return wrapper

