def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    # Check if the input is a non-empty tuple
    if not cmd or not isinstance(cmd, tuple):
        raise ValueError("Input must be a non-empty tuple of strings")

    # Convert the tuple to a list for manipulation
    cmd_list = list(cmd)

    # Check if the first element is a shebang
    if cmd_list and cmd_list[0].startswith('#!'):
        # Normalize the shebang path
        cmd_list[0] = cmd_list[0].replace('\\', '/')

    # Convert the list back to a tuple
    return tuple(cmd_list)

