def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        if not isinstance(e, Exception):
            raise ValueError("Input must be an exception instance")

        formatted_exc = traceback.format_exc().split('\n')
        formatted_str = []

        for frame in formatted_exc:
            if 'File' in frame:
                formatted_str.append(frame.split(',')[0])
                if len(formatted_str) >= max_path_level:
                    break
            elif '  File' not in frame and '    File' not in frame:
                formatted_str.append(frame.strip())
                if len(formatted_str) >= max_level + 2:
                    break

        return '\n'.join(formatted_str)

