        if exception.__context__:
            result += f"\nContext: {format_exception(exception.__context__)}"
        return result

    try:
        return format_exception(e) + "\nStack Trace:\n" + format_stack(e.__traceback__.tb_next, max_level)
    except AttributeError:
        return str(e)
    except Exception as err:
        return f"Error formatting exception: {err}"

