def integral(bins, edges):
    if len(bins) != len(edges) - 1:
        raise ValueError("The number of bins must be one less than the number of edges.")

    if not all(isinstance(x, (int, float)) for x in bins):
        raise ValueError("All elements in bins must be numbers.")

    if not all(isinstance(x, (int, float)) for x in edges):
        raise ValueError("All elements in edges must be numbers.")

    if any(b < 0 for b in bins):
        raise ValueError("All values in bins must be non-negative.")

    areas = [(edges[i] - edges[i-1]) * bin_val for i, bin_val in enumerate(bins)]
    return sum(areas)

