    VALUE_RE = re.compile(r'^\s*[a-zA-Z0-9_]+\s*$')

    errors = []

    def _validate(value, pattern, label_type):
        if not pattern.match(value):
            errors.append({str(value): f"Label {label_type} '{value}' does not match the regex"})

    for key, value in labels.items():
        if not isinstance(key, (str, bytes)):
            _validate(key, KEY_RE, 'key')
