def _extract_number_and_supplment_from_issue_element(issue):
    number = None
    suppl = None

    if not issue.startswith('<issue>') or not issue.endswith('</issue>'):
        return number, suppl

    issue_content = issue[6:-7].strip()

    if 'spe' in issue_content.lower():
        suppl = 'spe'
        number = 0
    elif 'suppl' in issue_content.lower():
        suppl = 'suppl'
        number = 0
    else:
