def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        value, unit = size[:-1], size[-1].upper()
        if unit == 'K':
            return int(float(value) * 1024)
        elif unit == 'M':
            return int(float(value) * 1024 * 1024)
        elif unit == 'G':
            return int(float(value) * 1024 * 1024 * 1024)
        elif unit == 'T':
            return int(float(value) * 1024 * 1024 * 1024 * 1024)
        elif unit == 'P':
            return int(float(value) * 1024 * 1024 * 1024 * 1024 * 1024)
        elif unit == 'E':
            return int(float(value) * 1024 * 1024 * 1024 * 1024 * 1024 * 1024)
        else:
            return int(value)
    except (ValueError, IndexError):
        raise ValueError("Invalid size format")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    units = {'B': 1, 'K': 1024, 'M': 1024**2, 'G': 1024**3, 'T': 1024**4, 'P': 1024**5, 'E': 1024**6}
    if not size:
        raise ValueError("Size cannot be empty")

    last_char = size[-1].upper()
    if last_char not in units:
        numeric_part = size
    else:
        numeric_part = size[:-1]

    try:
        numeric_value = int(numeric_part)
    except ValueError:
        raise ValueError("Invalid numeric part in size string")

    return numeric_value * units.get(last_char, 1)

