def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet or not string:
        raise ValueError("Both alphabet and string must be non-empty")

    try:
        return sum(alphabet.index(char) * (len(alphabet) ** idx) for idx, char in enumerate(reversed(string)))
    except ValueError as e:
        raise ValueError(f"Character '{e.args[0]}' not found in alphabet") from e

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    num_map = {char: idx for idx, char in enumerate(alphabet)}
    result = 0
    for char in string:
        if char not in num_map:
            raise ValueError(f"Character {char} not in alphabet")
        result = result * len(alphabet) + num_map[char]
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not alphabet or not string:
        raise ValueError("Alphabet and string must not be empty")

    if any(char not in alphabet for char in string):
        raise ValueError("String contains characters not in the alphabet")

    base = len(alphabet)
    number = 0

    for char in string:
        number = number * base + alphabet.index(char)

    return number

