def subprocess_run_helper(func, *args, timeout, extra_env=None):
    try:
        if extra_env:
            result = subprocess.run([func] + list(args), timeout=timeout, env={**os.environ, **extra_env})
        else:
            result = subprocess.run([func] + list(args), timeout=timeout)
        return result
    except TimeoutExpired as e:
        raise TimeoutError(f"Subprocess timed out after {timeout} seconds.") from e
