def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    команда = [commands] + args
    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    try:
        result = subprocess.run(команда, cwd=cwd, env=env, stderr=stderr, text=True, check=True)
        if verbose:
            print(result.stdout)
        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with returncode {e.returncode}: {e.stderr}")
        return e.stderr
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        return str(e)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not commands:
        raise ValueError("No commands provided")

    if not args:
        raise ValueError("No arguments provided")

    command = [commands]
    command.extend(args)

    try:
        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = None

        result = subprocess.run(command, cwd=cwd, env=env, check=True, stdout=subprocess.PIPE, stderr=stderr)

        if verbose:
            print(result.stdout.decode())

        return result.stdout

    except subprocess.CalledProcessError as e:
        print(f"Command failed with return code {e.returncode}: {e}")
        print(e.stderr.decode())
        return None

