def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    nodes = set(graph.allSubjects())

    while nodes:
        child = nodes.pop()
        parents = set(graph.objects(child, prop))
        if not parents:
            roots.add(child)
        else:
            nodes.update(parents)

    return roots

