def from_ticks(cls, ticks: int, tz: Optional[timezone] = None) -> 'Time':
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        # Convert ticks to seconds
        seconds = ticks // 10**9

        # Create a naive datetime object
        naive_time = datetime(1970, 1, 1) + timedelta(seconds=seconds)

        if tz:
            # Localize the naive datetime object with the provided timezone
            localized_time = tz.localize(naive_time)
        else:
            # Keep it naive
            localized_time = naive_time

        return cls(localized_time)

    def __init__(self, dt):
        self._dt = dt

    def __repr__(self):
        return f"Time({self._dt})"

