    return type

def determineMetaclass(bases, explicit_mc=None):
        """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

        # Check for explicit metaclass
        if explicit_mc is not None:
            return explicit_mc

        # Determine metaclass from bases
        for base in bases:
            if hasattr(base, '__metaclass__'):
                return base.__metaclass__

        # Fallback to type for new-style classes
        if all(issubclass(b, object) for b in bases):
            return type

        # Fallback to type for old-style classes
        return None

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: Tuple of base classes
    :param explicit_mc: Explicitly provided metaclass
    :return: Metaclass to use
    """
    if explicit_mc is not None:
        return explicit_mc

    meta_classes = set()
    for base in bases:
        if hasattr(base, '__metaclass__'):
            meta_classes.add(base.__metaclass__)
        elif hasattr(base, '__class__') and hasattr(base.__class__, '__metaclass__'):
            meta_classes.add(base.__class__.__metaclass__)

    if len(meta_classes) == 1:
        return next(iter(meta_classes))
    elif len(meta_classes) > 1:
        raise TypeError("Multiple metaclasses found: {}".format(meta_classes))
    else:
        return type

