def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        raise ValueError("Empty document provided")

    try:
        # Try parsing as JSON
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except json.JSONDecodeError:
        pass

    try:
        # Try parsing as XRD
        root = ET.fromstring(document)
        if root.tag.endswith('XRD'):
            entities = root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link')
            result = {}
            for entity in entities:
                rel = entity.get('rel')
                href = entity.get('href')
                if rel and href:
                    result[rel] = href
            return result
    except ET.ParseError:
        pass

