def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param root_subparsers: the subparser object to extend.
    """
    try:
        # Assuming self.command is a dictionary with command options
        for command_name, command_info in self.command.items():
            command_parser = root_subparsers.add_parser(command_name, help=command_info['help'])
            for option, details in command_info['options'].items():
                command_parser.add_argument(option, **details)
    except AttributeError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

